/* Mascot sprites (astronaut kid) — artwork by the Ink Squadron team */
var MASCOT = { ready: false, img: {}, src: {
  happy: 'data:image/webp;base64,',
  sad: 'data:image/webp;base64,',
  attack: 'data:image/webp;base64,',
  satisfied: 'data:image/webp;base64,',
  surprised: 'data:image/webp;base64,',
  afraid: 'data:image/webp;base64,',
  thumbs: 'data:image/webp;base64,',
  ready: 'data:image/webp;base64,',
  hand: 'data:image/webp;base64,',
} };
(function () { let left = 0; for (const k in MASCOT.src) { left++; const im = new Image(); im.onload = () => { if (--left === 0) MASCOT.ready = true; }; im.src = MASCOT.src[k]; MASCOT.img[k] = im; } })();
